# longest inverted repeat (palindrome w/ spacer)
def has_inv(seq,k):
    rc=revcomp(seq)
    seen={}
    for i in range(len(seq)-k+1):
        seen.setdefault(seq[i:i+k],[]).append(i)
    for j in range(len(rc)-k+1):
        km=rc[j:j+k]
        if km in seen:
            # map rc position j to original  [n-j-k, n-j)
            return (seen[km][0], n-j-k, km)
    return None
