import re
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

# approximate repeat scan: for k=20 anchor, find second occurrence within hamming distance
def approx_repeats(s,k=20,maxmm=3,mink=30):
    hits={}
    for i in range(len(s)-k+1):
        hits.setdefault(s[i:i+k],[]).append(i)
    found=[]
    # extend from each exact kmer match
    for i in range(len(s)-k+1):
        a=s[i:i+k]
        for j in hits.get(a,[]):
            if j<=i: continue
            # extend
            L=k
            while i+L<len(s) and j+L<len(s) and s[i+L]==s[j+L]: L+=1
            if L>=mink:
                found.append((L,i+1,j+1))
    # dedupe keep longest
    found.sort(reverse=True)
    return found[:10]
print("approx direct repeats:")
for f in approx_repeats(seq): print(f)

# inverted approx
def approx_inv(s,k=20,mink=30):
    r=rc(s)
    hits={}
    for i in range(len(s)-k+1):
        hits.setdefault(s[i:i+k],[]).append(i)
    found=[]
    for j in range(len(r)-k+1):
        a=r[j:j+k]
        for i in hits.get(a,[]):
            L=k
            while i+L<len(s) and j+L<len(r) and s[i+L]==r[j+L]: L+=1
            if L>=mink:
                # original second arm coords: r index j.. -> original n-j-L .. n-j
                found.append((L,i+1,n-(j)-L+1,n-j+1))
    found.sort(reverse=True)
    return found[:10]
